class ProviderResourceScope(Contract):
    """Backend-owned grant attribution for an actual provider resource.

    The reference is never a bearer; backend retains issuance, provider tokens,
    resource admission and billing export settlement.
    """

    provider: Literal["modal"]
    grant: ExactReference
    provider_resource_id: Identifier
    app_name: Identifier
    function_name: Identifier
