    @model_validator(mode="after")
    def scoped_resource(self):
        if (
            self.grant.authority != "backend"
            or self.grant.kind != "project_resource_grant"
        ):
            raise ValueError(
                "provider grant must cite backend project resource authority"
            )
        grant_id = str(UUID(self.grant.record_id))
        if (
            self.tags.get("grant_id") != grant_id
            or not self.tags.get("organization_id")
            or not self.tags.get("project_id")
        ):
            raise ValueError(
                "provider resource must retain exact grant and project tags"
            )
        return self


